import {cents,yuan} from './currency.js';
export const MATERIALS={lemon:{name:'柠檬',category:'原料',unit:'克',priceFen:2,recipe:50,priceLabel:'10 元 / 斤（500 克）',life:2,step:50},tea:{name:'白茶叶',category:'原料',unit:'克',priceFen:20,recipe:3,priceLabel:'10 元 / 50 克',life:30,step:3},sugar:{name:'白砂糖',category:'原料',unit:'克',priceFen:1,recipe:15,priceLabel:'5 元 / 斤（500 克）',life:60,step:15},cup:{name:'杯子',category:'包材',unit:'个',priceFen:20,recipe:1,priceLabel:'0.20 元 / 个',life:null,step:1},straw:{name:'吸管',category:'包材',unit:'根',priceFen:5,recipe:1,priceLabel:'0.05 元 / 根',life:null,step:1}};
export const RECIPE_COST=Object.values(MATERIALS).reduce((n,m)=>n+m.recipe*m.priceFen,0);
export function quantities(s){return Object.fromEntries(Object.keys(MATERIALS).map(k=>[k,(s.stockLots||[]).filter(l=>l.material===k).reduce((n,l)=>n+l.quantity,0)]));}
export function stockValue(s){return (s.stockLots||[]).reduce((n,l)=>n+l.quantity*MATERIALS[l.material].priceFen,0)+(s.readyCups||0)*RECIPE_COST;}
export function ensureStock(s){if(s.stockLots)return;const inv=s.tx.reduce((n,t)=>n+cents(t.delta.inventory||0),0),cups=inv/RECIPE_COST;s.stockLots=[];s.readyCups=0;if(s.day===1&&['first','credit','dusk','evening'].includes(s.phase)){s.readyCups=cups;}else{for(const [key,m]of Object.entries(MATERIALS))if(cups>0)s.stockLots.push({material:key,quantity:m.recipe*cups,received:s.day,expires:m.life===null?null:s.day+m.life});}}
export function possibleCups(s){ensureStock(s);const q=quantities(s);return (s.readyCups||0)+Math.min(...Object.entries(MATERIALS).map(([k,m])=>Math.floor(q[k]/m.recipe)));}
export function suggestedCart(s,target=5){ensureStock(s);const q=quantities(s),rawTarget=Math.max(0,target-(s.readyCups||0));return Object.fromEntries(Object.entries(MATERIALS).map(([k,m])=>[k,Math.max(0,rawTarget*m.recipe-q[k])]));}
export function quote(cart){if(!cart||Object.keys(cart).some(k=>!MATERIALS[k]))return null;let cost=0;for(const [key,m]of Object.entries(MATERIALS)){const qty=cart[key]??0;if(!Number.isSafeInteger(qty)||qty<0||qty>100000)return null;cost+=qty*m.priceFen;}return {costFen:cost,cost:yuan(cost)};}
export function receive(s,cart){for(const [key,m]of Object.entries(MATERIALS)){const qty=cart[key]||0;if(qty)s.stockLots.push({material:key,quantity:qty,received:s.day,expires:m.life===null?null:s.day+m.life});}}
export function consumeRecipe(s,count){const q=quantities(s);if(Object.entries(MATERIALS).some(([k,m])=>q[k]<m.recipe*count))return false;for(const [key,m]of Object.entries(MATERIALS)){let left=m.recipe*count;for(const lot of s.stockLots.filter(l=>l.material===key).sort((a,b)=>(a.expires??Infinity)-(b.expires??Infinity)||a.received-b.received)){const n=Math.min(left,lot.quantity);lot.quantity-=n;left-=n;}}s.stockLots=s.stockLots.filter(l=>l.quantity>0);return true;}
export function takeCup(s){if(s.readyCups>0){s.readyCups--;return true;}return consumeRecipe(s,1);}
export function expiry(s){ensureStock(s);const bad=s.stockLots.filter(l=>l.expires!==null&&l.expires<=s.day),costFen=bad.reduce((n,l)=>n+l.quantity*MATERIALS[l.material].priceFen,0);s.stockLots=s.stockLots.filter(l=>!bad.includes(l));return {cost:yuan(costFen),detail:bad.map(l=>MATERIALS[l.material].name+' '+l.quantity+MATERIALS[l.material].unit).join('、')};}
export function validateStock(s){if(!s.stockLots)return;if(!Array.isArray(s.stockLots)||s.stockLots.length>1000||!Number.isSafeInteger(s.readyCups)||s.readyCups<0||s.readyCups>100||s.stockLots.some(l=>!l||!MATERIALS[l.material]||!Number.isSafeInteger(l.quantity)||l.quantity<0||!Number.isInteger(l.received)||l.received<1||l.received>s.day||(l.expires!==null&&(!Number.isInteger(l.expires)||l.expires<=l.received))))throw Error('原料库存不正确');const ledger=s.tx.reduce((n,t)=>n+cents(t.delta.inventory||0),0);if(ledger!==stockValue(s))throw Error('原料明细与存货账目不一致');}
